insert into public.leader_playbook (type, prefix, title, content, note, tags, share_text, roleplay_prompt, mini_quiz, learning_carousel, legacy_source_code)
values
  ('principle', '01', '5 Cấp Độ Lãnh Đạo (John Maxwell)', 'Quản trị đội ngũ Sale Bảo hiểm là một nghệ thuật. Hãy đi qua các tình huống thực chiến dưới đây để xem bạn đang vận hành ở cấp độ nào:', null, array[]::text[], null, null, null, '{"situations":[{"question":"🔥 Cấp độ 1 (Quyền lực): Đội ngũ đang chững số cuối tháng. Bạn đăng vào group: ''Ai không đủ số tháng này sẽ bị cắt data''. Việc này sẽ dẫn đến kết quả gì?","options":["A. Team sợ và chạy số điên cuồng","B. Team chống đối ngầm và rục rịch nghỉ việc"],"correct_index":1,"correct_explanation":"Chính xác! Lạm dụng Cấp độ 1 có thể ra số ngắn hạn nhưng phá vỡ sự gắn kết. Đại lý sẽ làm ẩu, ép khách và cuối cùng là rời đi.","wrong_explanation":"Sai lầm! Sự sợ hãi (Cấp độ 1) không tạo ra doanh số bền vững. Nó chỉ khiến đại lý đối phó bằng những hợp đồng ảo."},{"question":"🔥 Cấp độ 2 (Quan hệ): Một đại lý mới đang rất nản vì bị khách hàng từ chối liên tục. Bạn làm gì để áp dụng Cấp độ 2?","options":["A. Nhắc nhở quy định phải gọi 20 cuộc/ngày","B. Rủ đi cà phê, lắng nghe những ấm ức của họ"],"correct_index":1,"correct_explanation":"Tuyệt vời! Cấp độ 2 là khi nhân sự làm vì ''nể'' và ''quý'' bạn. Sự thấu cảm lúc này quan trọng hơn KPI.","wrong_explanation":"Nhắc quy định lúc này là bạn đang dùng Cấp độ 1 (Ép buộc). Hãy lùi lại, dùng Cấp độ 2 (Xây dựng quan hệ) để xoa dịu họ trước."},{"question":"🔥 Cấp độ 3 (Kết quả): Lời nói của bạn bắt đầu mất trọng lượng với các đại lý kỳ cựu. Cách nhanh nhất để lấy lại uy tín (Cấp độ 3) là gì?","options":["A. Tự mình chốt một HĐ lớn (MDRT) để làm gương","B. Tổ chức họp team và yêu cầu mọi người tôn trọng Leader"],"correct_index":0,"correct_explanation":"Quá chuẩn! Cấp độ 3 là ''Dẫn dắt bằng kết quả''. Khi bạn tạo ra thành tích thực tế, đội ngũ sẽ tự động ngưỡng mộ và làm theo.","wrong_explanation":"Đòi hỏi sự tôn trọng bằng lời nói là vô ích. Ở Cấp độ 3, nhân sự chỉ nghe bạn khi bạn chứng minh được năng lực thực chiến (MDRT/COT)."},{"question":"🔥 Cấp độ 4 (Phát triển người khác): Bạn có một ''Ngôi sao bán hàng'' rất giỏi nhưng hay tự mãn. Bạn áp dụng Cấp độ 4 như thế nào?","options":["A. Dùng nội quy cứng rắn để kìm hãm cái tôi của họ","B. Giao cho họ quyền chủ trì huấn luyện người mới"],"correct_index":1,"correct_explanation":"Đỉnh cao! Cấp độ 4 là tạo ra những Leader mới. Khi trao quyền, bạn vừa giữ chân được nhân tài, vừa dẹp bỏ được cái tôi kiêu ngạo của họ.","wrong_explanation":"Kìm hãm họ sẽ khiến họ bỏ sang công ty khác. Hãy nâng tầm họ lên bằng cách trao quyền đào tạo người khác (Cấp độ 4)."},{"question":"🔥 Cấp độ 5 (Sự tôn trọng/Đỉnh cao): Đâu là dấu hiệu cho thấy bạn đã đạt đến Cấp độ 5 trong ngành Bảo hiểm?","options":["A. Doanh số team luôn đứng Top 1 công ty","B. Bạn rời đi, nhưng di sản và văn hóa team vẫn tự vận hành tốt"],"correct_index":1,"correct_explanation":"Hoàn hảo! Cấp độ 5 (Pinnacle) là khi bạn trở thành biểu tượng. Tầm ảnh hưởng của bạn vượt ra khỏi chức danh và doanh số hiện tại.","wrong_explanation":"Doanh số Top 1 chỉ mới là Cấp độ 3 (Kết quả). Cấp độ 5 là sự trường tồn của văn hóa và di sản bạn để lại ngay cả khi bạn không có mặt."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Lãnh đạo không phải là cái ghế bạn ngồi, mà là hành trình bạn đi từ (1) Quyền lực -> (2) Quan hệ -> (3) Kết quả -> (4) Phát triển người khác -> (5) Di sản.","homework":"📝 BÀI TẬP NHỎ: Tuần này, hãy thử làm MỘT hành động thuộc Cấp độ 4 (Trao quyền/Phát triển) với một thành viên đang gặp khó khăn nhé!"}}'::jsonb, 'v95-leader-principle-01'),
  ('principle', '02', 'Tư Duy Tảng Băng Trôi (The Iceberg Model)', 'Biểu hiện bên ngoài chỉ là 10% bề nổi. 90% phần chìm là nỗi sợ, áp lực tài chính, khủng hoảng cá nhân. Hãy khám phá qua các tình huống sau:', null, array[]::text[], null, null, null, '{"situations":[{"question":"🔥 Tình huống 1: Một đại lý mới liên tục trễ deadline nộp báo cáo tuần. Phản xạ đầu tiên của bạn là gì?","options":["A. Nhắc nhở quy định phạt của văn phòng","B. Đặt câu hỏi: ''Dạo này em có đang vướng mắc gì không?''"],"correct_index":1,"correct_explanation":"Tuyệt vời! Bạn đang chạm vào 90% phần chìm. Có thể họ đang gặp khủng hoảng thời gian hoặc chưa hiểu cách làm.","wrong_explanation":"Phạt ngay lập tức chỉ mới tác động vào 10% bề nổi và dễ làm TVV bất mãn. Hãy lùi lại tìm hiểu nguyên nhân gốc rễ."},{"question":"🔥 Tình huống 2: TVV bỗng nhiên im lặng, không tham gia thảo luận trong group Zalo team suốt 3 ngày. Bạn nên xử lý thế nào?","options":["A. Nhắn tin riêng hỏi thăm nhẹ nhàng xem bạn có ổn không","B. Nhắc nhở mọi người tương tác đủ chỉ tiêu group"],"correct_index":0,"correct_explanation":"Chính xác! Sự im lặng đột ngột là tín hiệu chìm của áp lực hoặc biến cố. Quan tâm 1-1 sẽ chạm đến trái tim họ.","wrong_explanation":"Đổ lỗi hoặc ra rả quy định tương tác lúc này chỉ làm khoảng cách giữa bạn và TVV xa thêm."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Đừng bao giờ phản ứng vội vàng với hiện tượng bề nổi. Kỷ luật mà thiếu sự thấu cảm sẽ chỉ tạo ra khoảng cách.","homework":"📝 BÀI TẬP NHỎ: Hôm nay, hãy chọn 1 TVV đang có vẻ chìm lắng và nhắn tin hỏi thăm riêng một cách chân thành nhất."}}'::jsonb, 'v95-leader-principle-02'),
  ('principle', '03', 'Kỹ thuật Đào Sâu Gốc Rễ (5 Whys)', 'Đừng làm ''từ điển sống'' giải quyết hộ tuyến dưới. Hãy dùng chuỗi câu hỏi ''Tại sao'' để họ tự ngộ ra vấn đề.', null, array[]::text[], null, null, null, '{"situations":[{"question":"🔥 Tình huống 1: TVV than vãn: ''Em không tìm được khách hàng nào cả''. Đâu là câu hỏi mở giúp họ tự tư duy?","options":["A. Sao em không thử gọi lại danh sách khách cũ?","B. Tại sao dạo này em lại thấy khó tìm khách vậy?"],"correct_index":1,"correct_explanation":"Đúng! Câu (B) buộc TVV phải tự phân tích xem khâu tiếp cận hay kịch bản của mình đang vướng ở đâu.","wrong_explanation":"Bạn lại mắc bệnh mớm sẵn giải pháp rồi. Hãy để họ tự suy nghĩ bằng câu hỏi mở (B)."},{"question":"🔥 Tình huống 2: TVV nói ''Khách nào nghe bảo hiểm cũng chê đắt''. Bạn tiếp tục hỏi câu Why thứ hai thế nào?","options":["A. Vậy em phải đổi sang bán thẻ sức khỏe rẻ hơn","B. Theo em, vì sao khách lại cảm thấy số tiền đó là đắt?"],"correct_index":1,"correct_explanation":"Chính xác! Đào sâu vào nhận thức của khách hàng giúp TVV nhận ra họ chưa neo được giá trị bảo vệ.","wrong_explanation":"Đó là cách giải quyết thay cho nhân viên. Hãy bắt họ tư duy bằng cách hỏi sâu vào nguyên nhân."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Đưa ra câu trả lời chỉ giúp họ giải quyết 1 lần. Dạy họ cách đặt câu hỏi sẽ giúp họ tự giải quyết hàng ngàn lần.","homework":"📝 BÀI TẬP NHỎ: Trong cuộc họp 1-1 tới, tuyệt đối không đưa ra lời khuyên ngay. Hãy thử dùng ít nhất 3 câu hỏi ''Tại sao/Như thế nào''."}}'::jsonb, 'v95-leader-principle-03'),
  ('principle', '04', 'Khung Phản Hồi Đa Chiều (SBI Model)', 'Situation (Tình huống) - Behavior (Hành vi khách quan) - Impact (Tác động). Góp ý vào hành vi, tuyệt đối không dán nhãn con người.', null, array[]::text[], null, null, null, '{"situations":[{"question":"🔥 Tình huống 1: Một Top Sale có thái độ trịch thượng trong cuộc họp. Đâu là cách nói chuẩn chữ B (Behavior)?","options":["A. Dạo này em làm việc rất kiêu ngạo","B. Sáng nay lúc họp, em ngắt lời bạn A hai lần"],"correct_index":1,"correct_explanation":"Quá chuẩn! Bạn nêu rõ sự kiện và hành vi đếm được, không hề tấn công cá nhân.","wrong_explanation":"''Kiêu ngạo'' là nhãn dán chủ quan, sẽ khiến Top Sale lập tức xù lông phòng thủ."},{"question":"🔥 Tình huống 2: Sau khi nêu Behavior, đến phần Impact (Tác động), bạn nên nói gì?","options":["A. Làm vậy là sai nội quy văn phòng đấy nhé!","B. Việc đó làm các bạn mới cảm thấy ngại không dám phát biểu"],"correct_index":1,"correct_explanation":"Chính xác! Chỉ ra tác động thực tế giúp nhân sự nhận thức rõ hậu quả hành vi của họ đối với tập thể.","wrong_explanation":"Dùng nội quy để áp đặt sẽ làm lu mờ đi ý nghĩa giáo dục của phản hồi mang tính xây dựng."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Con người dễ dàng chấp nhận sửa đổi khi họ biết hành vi cụ thể nào đang ảnh hưởng xấu đến người khác, thay vì bị phán xét chung chung.","homework":"📝 BÀI TẬP NHỎ: Chuẩn bị một thông điệp góp ý theo đúng khung S-B-I cho một vấn đề tồn đọng trong tuần này."}}'::jsonb, 'v95-leader-principle-04');
